# ---------------------------------------------------------------------------
# Legacy_Validator.ps1  (single file: script + embedded validator)
#
# Validates legacy (BINK1998 / BINK2002) product keys without pidgenx.dll.
#   msft:rm/algorithm/pkey/980        -> Pid1998
#   msft:rm/algorithm/pkey/985 / 986  -> Pid2002
#
# The validator is pkeyLegacy.cs (minified) -> GZip -> Base64, unpacked and
# compiled with Add-Type at start-up. PowerShell 5.1 and 7, any CPU.
#
# Legacy Key Collection Source's
# https://raw.githubusercontent.com/techguy16/umsktpy/refs/heads/nobridge/keys.json
# https://github.com/ntriver-org/PKeyMaster/blob/main/PKeyMaster/BIN/PKeyConfigs/Pre-Vista Custom Made/Pre-Vista (Windows 98 to XP - Office 2000 to 2007 - etc)/pkeyconfig-custom-made.xrm-ms
#
# Test keys:
#   980 : B2Y39-43MG6-MMGRG-7VKCF-VXMCM   -> Group 44,  Ch 366, Seq 659088
#   986 : VCFQD-V9FX9-46WVH-K3CD4-4J3JM   -> Group 100, Ch 652, Seq 828461
# ---------------------------------------------------------------------------

param(
    [string]$CdKey,
    [string]$LicenseXml,
    [switch]$BuiltIn,         # use the BINKs compiled into the C# class (no XML needed)
    [string]$BinksJson,       # use BINKs from a JSON file (Legacy_Binks.json format)
    [switch]$AllBinks,        # check every BINK (default: stop at first match)
    [int]$Threads = 0         # 0 = one per CPU core, 1 = serial
)

# Multi Platform Version
# .\Pkey-ValidateLegacy.ps1 -CDKey "B2Y39-43MG6-MMGRG-7VKCF-VXMCM" -BuiltIn
# .\Pkey-ValidateLegacy.ps1 -CDKey "B2Y39-43MG6-MMGRG-7VKCF-VXMCM" -BinksJson  '.\PKeyConfigs\Legacy_Binks.json'
# .\Pkey-ValidateLegacy.ps1 -CDKey "B2Y39-43MG6-MMGRG-7VKCF-VXMCM" -LicenseXml '.\PKeyConfigs\Legacy_License.xml'

Set-Location $PSScriptRoot
[Environment]::CurrentDirectory = $PSScriptRoot

#region Parameter checks
function Stop-Usage([string]$Message) {
    Write-Host "Error: $Message" -ForegroundColor Red
    Write-Host ''
    Write-Host 'Usage (pick exactly one BINK source):'
    Write-Host '  .\Pkey-ValidateLegacy.ps1 -CDKey "XXXXX-XXXXX-XXXXX-XXXXX-XXXXX" -BuiltIn'
    Write-Host '  .\Pkey-ValidateLegacy.ps1 -CDKey "XXXXX-XXXXX-XXXXX-XXXXX-XXXXX" -LicenseXml ''.\PKeyConfigs\Legacy_License.xml'''
    Write-Host '  .\Pkey-ValidateLegacy.ps1 -CDKey "XXXXX-XXXXX-XXXXX-XXXXX-XXXXX" -BinksJson  ''.\PKeyConfigs\Legacy_Binks.json'''
    Write-Host 'Options: -AllBinks (check every BINK), -Threads N (0 = one per core, 1 = serial)'
    exit 1
}

# relative paths are taken from the script folder, absolute paths are used as they are
function Resolve-InputFile([string]$Path, [string]$Name) {
    $full = if ([IO.Path]::IsPathRooted($Path)) { $Path } else { Join-Path $PSScriptRoot $Path }
    if (-not (Test-Path -LiteralPath $full -PathType Leaf)) { Stop-Usage "$Name file not found: $full" }
    return (Resolve-Path -LiteralPath $full).ProviderPath
}

# key: 25 characters from the legacy alphabet (dashes and spaces are ignored)
if ([string]::IsNullOrWhiteSpace($CdKey)) { Stop-Usage 'missing -CDKey' }
$keyText = ($CdKey -replace '[-\s]', '').ToUpperInvariant()
if ($keyText.Length -ne 25) { Stop-Usage "key must have 25 characters (not counting dashes), got $($keyText.Length): $CdKey" }
if ($keyText -notmatch '^[BCDFGHJKMPQRTVWXY2346789]{25}$') {
    $badChars = (($keyText.ToCharArray() | Where-Object { 'BCDFGHJKMPQRTVWXY2346789'.IndexOf($_) -lt 0 } | Select-Object -Unique) -join ' ')
    Stop-Usage "key has characters that legacy keys never use: $badChars"
}

# BINK source: exactly one of -BuiltIn / -LicenseXml / -BinksJson
$sources = @()
if ($BuiltIn)                                     { $sources += '-BuiltIn' }
if ($PSBoundParameters.ContainsKey('LicenseXml')) { $sources += '-LicenseXml' }
if ($PSBoundParameters.ContainsKey('BinksJson'))  { $sources += '-BinksJson' }
if ($sources.Count -eq 0) { Stop-Usage 'no BINK source given' }
if ($sources.Count -gt 1) { Stop-Usage ("use only one BINK source, got: {0}" -f ($sources -join ', ')) }

if ($PSBoundParameters.ContainsKey('LicenseXml')) {
    if ([string]::IsNullOrWhiteSpace($LicenseXml)) { Stop-Usage '-LicenseXml needs a file path' }
    $LicenseXml = Resolve-InputFile $LicenseXml 'License XML'
}
if ($PSBoundParameters.ContainsKey('BinksJson')) {
    if ([string]::IsNullOrWhiteSpace($BinksJson)) { Stop-Usage '-BinksJson needs a file path' }
    $BinksJson = Resolve-InputFile $BinksJson 'BINK JSON'
}

if ($Threads -lt 0) { Stop-Usage "-Threads must be 0 or more, got $Threads" }
#endregion
